<script setup>
import { computed, onMounted, ref } from 'vue'
import { api } from '../api'

const emit = defineEmits(['settings', 'notice'])
const alerts = ref([])
const sufficientHistory = ref(true)
const historyDays = ref(0)
const severity = ref('Semua tingkat')
const status = ref('Semua status')
const from = ref('')
const to = ref('')
const loading = ref(true)
const money = (value) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(Number(value || 0))
const dateLabel = (value) => new Date(`${value}T00:00:00`).toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' })
const filtered = computed(() => alerts.value.filter((alert) => (severity.value === 'Semua tingkat' || alert.severity === severity.value) && (status.value === 'Semua status' || alert.status === status.value) && (!from.value || alert.detectedAt >= from.value) && (!to.value || alert.detectedAt <= to.value)))
async function load() {
  loading.value = true
  try { const result = await api('/alerts'); alerts.value = result.alerts; sufficientHistory.value = result.sufficientHistory; historyDays.value = result.historyDays }
  catch (error) { emit('notice', error.message) }
  finally { loading.value = false }
}
onMounted(load)
</script>

<template>
  <div class="content alerts-page">
    <div class="page-intro"><div><div class="eyebrow">EARLY WARNING SYSTEM</div><h2>Peringatan keuangan</h2><p>Pantau proyeksi saldo yang berisiko turun di bawah batas aman.</p></div><button class="button secondary" @click="load">Muat ulang</button></div>
    <div class="alert-summary"><div class="summary-count" :class="alerts.length ? 'has-risk' : ''">{{ alerts.length }}</div><div><strong>{{ alerts.length ? 'Peringatan aktif' : sufficientHistory ? 'Tidak ada indikasi risiko dari pola terakhir' : 'Data prediksi belum cukup' }}</strong><p>{{ alerts.length ? 'Ini perkiraan berbasis rata-rata 30 hari terakhir, bukan kepastian.' : sufficientHistory ? 'Proyeksi berbasis rata-rata 30 hari terakhir masih di atas batas minimum.' : `Baru ada transaksi pada ${historyDays} hari berbeda dari 30 hari terakhir. Perlu setidaknya 7 hari transaksi sebelum peringatan prediksi ditampilkan.` }}</p></div><button class="text-button" @click="emit('settings')">Buka batas minimum kas →</button></div>
    <section class="panel alert-filters"><label>Tingkat risiko<select v-model="severity"><option>Semua tingkat</option><option>Tinggi</option><option>Sedang</option><option>Rendah</option></select></label><label>Status<select v-model="status"><option>Semua status</option><option>Aktif</option></select></label><label>Terdeteksi sejak<input v-model="from" type="date"></label><label>Sampai tanggal<input v-model="to" type="date"></label></section>
    <div v-if="loading" class="panel loading-state">Memeriksa proyeksi saldo…</div>
    <div v-else-if="filtered.length" class="alert-list"><article v-for="alert in filtered" :key="alert.id" class="panel risk-card" :class="`risk-${alert.severity.toLowerCase()}`"><div class="risk-card-top"><div class="risk-heading"><span class="risk-mark">!</span><div><span class="risk-kicker">RISIKO SALDO KAS</span><h3>{{ alert.title }}</h3></div></div><div class="risk-badges"><span class="severity-badge" :class="`badge-${alert.severity.toLowerCase()}`">{{ alert.severity }}</span><span class="status-badge">{{ alert.status }}</span></div></div><p class="risk-reason">{{ alert.reason }}</p><div class="risk-numbers"><div><small>Saldo terproyeksi</small><strong class="text-red">{{ money(alert.projectedBalance) }}</strong></div><div><small>Batas minimum kas</small><strong>{{ money(alert.threshold) }}</strong></div><div><small>Tanggal indikatif, bukan kepastian</small><strong>{{ dateLabel(alert.expectedDate) }}</strong></div><div><small>Peringatan dibuat</small><strong>{{ dateLabel(alert.detectedAt) }}</strong></div></div><div class="suggestions"><strong>Langkah yang dapat ditinjau</strong><ul><li v-for="item in alert.suggestions" :key="item">{{ item }}</li></ul></div><div class="risk-card-footer"><span>Perkiraan linear dari rata-rata per hari kalender selama 30 hari terakhir.</span><button class="button secondary" @click="emit('settings')">Tinjau pengaturan kas</button></div></article></div>
    <article v-else-if="!loading" class="panel no-alerts"><div class="safe-check">{{ sufficientHistory ? '✓' : 'i' }}</div><h3>{{ alerts.length ? 'Tidak ada peringatan sesuai filter' : sufficientHistory ? 'Tidak ada indikasi risiko dari pola terakhir' : 'Data prediksi belum cukup' }}</h3><p>{{ alerts.length ? 'Ubah filter untuk melihat peringatan lain.' : sufficientHistory ? 'Rata-rata arus kas 30 hari terakhir memproyeksikan saldo di atas batas minimum. Ini perkiraan, bukan jaminan.' : `Baru ada transaksi pada ${historyDays} hari berbeda. Catat setidaknya 7 hari transaksi agar peringatan prediksi ditampilkan.` }}</p><button class="text-button" @click="emit('settings')">Periksa pengaturan kas →</button></article>
    <p class="alert-disclaimer">Peringatan merupakan estimasi dari data transaksi yang tercatat. Periksa kembali rencana kas sebelum mengambil keputusan.</p>
  </div>
</template>

<style>
.alert-summary{display:flex;align-items:center;gap:14px;padding:17px 20px;border:1px solid #E2E8F0;border-radius:10px;background:#fff;margin-bottom:16px}.summary-count{width:39px;height:39px;border-radius:9px;background:#DCFCE7;color:#15803D;display:grid;place-items:center;font-size:17px;font-weight:700}.summary-count.has-risk{background:#FEF3C7;color:#B45309}.alert-summary strong{font-size:14px;color:#172B4D}.alert-summary p{font-size:11px;color:#64748B;margin:4px 0 0}.alert-summary .text-button{margin-left:auto}.alert-filters{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px;margin-bottom:16px;padding:17px}.alert-filters label{display:grid;gap:7px;font-size:11px;color:#64748B;font-weight:600}.alert-filters select,.alert-filters input{border:1px solid #E2E8F0;background:#fff;border-radius:7px;padding:9px 10px;color:#172B4D;font-size:12px}.risk-card{padding:22px 24px;border-left:4px solid #B45309}.risk-card.risk-tinggi{border-left-color:#B91C1C}.risk-card-top,.risk-heading,.risk-badges,.risk-card-footer{display:flex;align-items:center}.risk-card-top{justify-content:space-between}.risk-heading{gap:12px}.risk-mark{width:32px;height:32px;border-radius:50%;display:grid;place-items:center;background:#FEF3C7;color:#B45309;font-weight:800}.risk-tinggi .risk-mark{background:#FEE2E2;color:#B91C1C}.risk-kicker{font-size:9px;font-weight:700;letter-spacing:.7px;color:#8793a4}.risk-heading h3{font-size:16px;color:#172B4D;margin:3px 0 0}.risk-badges{gap:7px}.severity-badge,.status-badge{padding:6px 9px;border-radius:5px;font-size:10px;font-weight:700}.badge-tinggi{background:#FEE2E2;color:#B91C1C}.badge-sedang{background:#FEF3C7;color:#B45309}.badge-rendah{background:#DCFCE7;color:#15803D}.status-badge{background:#F1F5F9;color:#526176}.risk-reason{font-size:13px;color:#526176;line-height:1.6;margin:18px 0}.risk-numbers{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;background:#F5F7FA;border-radius:8px;padding:15px}.risk-numbers div{display:grid;gap:6px}.risk-numbers small{font-size:10px;color:#64748B}.risk-numbers strong{font-size:12px;color:#172B4D}.suggestions{padding:17px 0 10px}.suggestions>strong{font-size:12px;color:#172B4D}.suggestions ul{margin:9px 0 0;padding-left:18px;display:grid;gap:6px;color:#526176;font-size:12px}.risk-card-footer{justify-content:space-between;border-top:1px solid #E2E8F0;padding-top:14px;margin-top:8px}.risk-card-footer>span,.alert-disclaimer{font-size:10px;color:#8290a2}.no-alerts{text-align:center;padding:45px 20px}.no-alerts .safe-check{margin:0 auto 12px}.no-alerts h3{font-size:16px;margin:0 0 6px;color:#172B4D}.no-alerts p{font-size:12px;color:#64748B;margin:0 0 10px}.alert-disclaimer{margin:15px 2px}.alert-list{display:grid;gap:12px}.loading-state{text-align:center;color:#64748B;padding:45px}@media(max-width:900px){.alert-filters{grid-template-columns:repeat(2,minmax(0,1fr))}.risk-numbers{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:520px){.alert-summary{flex-wrap:wrap}.alert-summary .text-button{width:100%;text-align:left;margin:0}.alert-filters{grid-template-columns:1fr}.risk-card{padding:18px 15px}.risk-card-top{align-items:flex-start;gap:10px;flex-direction:column}.risk-numbers{padding:12px}.risk-card-footer{align-items:flex-start;gap:10px;flex-direction:column}}
</style>
